'use client';

import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import {
  createContext,
  forwardRef,
  useContext,
  type ComponentProps,
  type ComponentRef,
} from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CloseIcon } from '@/lib/moduix/icons/ui';
import { Button } from '../button';
import { CloseButton } from '../close-button';
import { Input, type InputSize } from '../input';
import styles from './InputGroup.module.css';

type InputGroupSize = InputSize;

const InputGroupSizeContext = createContext<InputGroupSize>('md');

const InputGroup = forwardRef<
  HTMLDivElement,
  HTMLArkProps<'div'> & {
    size?: InputGroupSize;
  }
>(function InputGroup({ children, className, size = 'md', ...props }, ref) {
  return (
    <InputGroupSizeContext.Provider value={size}>
      <ark.div
        ref={ref}
        {...props}
        data-scope="input-group"
        data-part="root"
        data-slot="input-group-root"
        data-size={size}
        className={clsx(styles.root, className)}
      >
        {children}
      </ark.div>
    </InputGroupSizeContext.Provider>
  );
});

const InputGroupInput = forwardRef<ComponentRef<typeof Input>, ComponentProps<typeof Input>>(
  function InputGroupInput({ className, size, ...props }, ref) {
    const groupSize = useContext(InputGroupSizeContext);

    return (
      <Input
        ref={ref}
        className={clsx(styles.input, className)}
        size={size ?? groupSize}
        {...props}
      />
    );
  },
);

const InputGroupAddon = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(function InputGroupAddon(
  { className, ...props },
  ref,
) {
  return (
    <ark.span
      ref={ref}
      {...props}
      data-scope="input-group"
      data-part="addon"
      data-slot="input-group-addon"
      className={clsx(styles.addon, className)}
    />
  );
});

const InputGroupText = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(function InputGroupText(
  { className, ...props },
  ref,
) {
  return (
    <ark.span
      ref={ref}
      {...props}
      data-scope="input-group"
      data-part="text"
      data-slot="input-group-text"
      className={clsx(styles.text, className)}
    />
  );
});

const InputGroupButton = forwardRef<HTMLButtonElement, ComponentProps<typeof Button>>(
  function InputGroupButton(
    { className, variant = 'ghost', size, type = 'button', ...props },
    ref,
  ) {
    const groupSize = useContext(InputGroupSizeContext);

    return (
      <Button
        ref={ref}
        {...props}
        data-slot="input-group-button"
        className={clsx(styles.button, className)}
        variant={variant}
        size={size ?? groupSize}
        type={type}
      />
    );
  },
);

const InputGroupClearTrigger = forwardRef<
  HTMLButtonElement,
  ComponentProps<typeof CloseButton> & { size?: InputGroupSize }
>(function InputGroupClearTrigger(
  {
    className,
    children,
    size,
    type = 'button',
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    ...props
  },
  ref,
) {
  const groupSize = useContext(InputGroupSizeContext);

  return (
    <CloseButton
      ref={ref}
      {...props}
      data-scope="input-group"
      data-part="clear-trigger"
      data-slot="input-group-clear-trigger"
      data-size={size ?? groupSize}
      className={clsx(styles.clearTrigger, className)}
      type={type}
      aria-label={ariaLabel ?? (ariaLabelledBy == null ? a11yLabels.clearInput : undefined)}
      aria-labelledby={ariaLabelledBy}
    >
      {children ?? <CloseIcon />}
    </CloseButton>
  );
});

export {
  InputGroup,
  InputGroupClearTrigger,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
};
export type { InputGroupSize };

@layer moduix.components {
  /* The root and the grouped input both carry `data-size`, so a local input size keeps its own padding. */
  .root,
  .input {
    --_input-group-height: var(--moduix-size-md);
    --_input-group-padding-x: var(--moduix-spacing-3-5);
    --_input-group-font-size: var(--moduix-text-md);
    --_input-group-line-height: var(--moduix-line-height-text-md);

    &[data-size='xs'] {
      --_input-group-height: var(--moduix-size-xs);
      --_input-group-padding-x: var(--moduix-spacing-2-5);
      --_input-group-font-size: var(--moduix-text-xs);
      --_input-group-line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'] {
      --_input-group-height: var(--moduix-size-sm);
      --_input-group-padding-x: var(--moduix-spacing-3);
      --_input-group-font-size: var(--moduix-text-sm);
      --_input-group-line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='lg'] {
      --_input-group-height: var(--moduix-size-lg);
      --_input-group-padding-x: var(--moduix-spacing-4);
      --_input-group-font-size: var(--moduix-text-lg);
      --_input-group-line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size='xl'] {
      --_input-group-height: var(--moduix-size-xl);
      --_input-group-padding-x: var(--moduix-spacing-4-5);
      --_input-group-font-size: var(--moduix-text-lg);
      --_input-group-line-height: var(--moduix-line-height-text-lg);
    }
  }

  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-input-group-width, 100%);
    min-height: var(--moduix-input-group-height, var(--_input-group-height));
    align-items: stretch;
    overflow: hidden;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-input-group-radius, var(--moduix-radius-md));
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font-size: var(--_input-group-font-size);
    line-height: var(--_input-group-line-height);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:focus-within {
      outline-color: var(--moduix-color-ring);
    }

    &:has([data-slot='input-root']:is([data-invalid], [aria-invalid='true'])) {
      border-color: var(--moduix-color-destructive);

      &:focus-within {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &:has([data-slot='input-root']:is([data-disabled], :disabled)) {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  /* Wins over the Input root styles regardless of stylesheet order. */
  .root .input {
    min-height: 0;
    flex: 1 1 auto;
    border: 0;
    border-radius: 0;
    background-color: transparent;
    outline: 0;
    padding-inline: var(--_input-group-padding-x);
  }

  .addon,
  .text {
    box-sizing: border-box;
    display: inline-flex;
    min-width: 0;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    padding-inline: var(--_input-group-padding-x);
    color: var(--moduix-color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }

  .addon {
    border-inline: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    background-color: var(--moduix-color-muted);

    &:first-child {
      border-inline-start: 0;
    }

    &:last-child {
      border-inline-end: 0;
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-size-xs);
    --moduix-close-button-icon-size: var(--moduix-spacing-4);
    --moduix-close-button-focus-ring-width: var(--moduix-border-width-sm);
    --moduix-close-button-focus-ring-offset: var(--moduix-border-width-sm);
    align-self: center;
    margin-inline-end: var(--moduix-spacing-2);

    &[data-size='xs'] {
      --moduix-close-button-size: var(--moduix-spacing-5);
    }
  }

  /* The slot attribute outranks Button's `[data-size]` rules, which would keep its own height. */
  .root .button[data-slot='input-group-button'] {
    min-height: auto;
    height: auto;
    align-self: stretch;
    padding-block: 0;
    border: 0;
    border-radius: 0;
  }
}
